import { NextRequest, NextResponse } from "next/server";
import { createServerClient } from "@/lib/supabase";
import { requireAdmin } from "@/lib/admin/gate";
import { BUCKETS, uploadBytes } from "@/lib/fabric/storage";
import { getPayloadPool } from "@/lib/website-cms";

export const dynamic = "force-dynamic";
export const maxDuration = 120;

/**
 * POST /api/admin/website/generate-image — generate a banner/pop-up
 * image with Pollinations (admin only). Body: { prompt, width?,
 * height? }. The generated bytes are STORED — in the design-files
 * bucket under website/generated-*, plus a Payload media row when
 * that insert succeeds — and the stored storage URL is returned.
 * Nothing is hotlinked: the caller saves the returned URL into the
 * banner/pop-up, never a pollinations.ai URL.
 *
 * The Pollinations key comes from POLLINATIONS_API_KEY in the server
 * environment (Vercel env, owner-set). Without it the route still
 * tries Pollinations' keyless image endpoint and says so in the
 * response; if generation fails it returns 502, never a fake URL.
 *
 * PROVENANCE NOTE (honest): this route is code-complete and gated
 * (401 without a staff session), but generation FROM A SIGNED-IN
 * SESSION is unproven — no signed-in session was available to this
 * worker. It must be clicked through by a signed-in admin before
 * anyone claims it works end to end.
 */
export async function POST(req: NextRequest) {
  const gate = await requireAdmin();
  if (gate.error) return gate.error;
  const body = await req.json().catch(() => null);
  const prompt = typeof body?.prompt === "string" ? body.prompt.trim() : "";
  if (!prompt || prompt.length > 1000) {
    return NextResponse.json({ error: "prompt is required (under 1000 characters)" }, { status: 400 });
  }
  const width = Number.isInteger(body?.width) && (body.width as number) > 0 && (body.width as number) <= 2048 ? body.width : 1200;
  const height = Number.isInteger(body?.height) && (body.height as number) > 0 && (body.height as number) <= 2048 ? body.height : 630;
  const key = process.env.POLLINATIONS_API_KEY ?? "";
  const url = new URL(`https://image.pollinations.ai/prompt/${encodeURIComponent(prompt)}`);
  url.searchParams.set("width", String(width));
  url.searchParams.set("height", String(height));
  url.searchParams.set("model", "flux");
  url.searchParams.set("nologo", "true");
  if (key) url.searchParams.set("token", key);
  let res: Response;
  try {
    res = await fetch(url.toString(), { headers: key ? { Authorization: `Bearer ${key}` } : {} });
  } catch (e) {
    return NextResponse.json({ error: `Pollinations request failed: ${e instanceof Error ? e.message : "network error"}` }, { status: 502 });
  }
  if (!res.ok) {
    return NextResponse.json({ error: `Pollinations returned ${res.status} — try a shorter prompt, or check the key in Vercel env` }, { status: 502 });
  }
  const contentType = res.headers.get("content-type") ?? "";
  if (!contentType.startsWith("image/")) {
    return NextResponse.json({ error: "Pollinations did not return an image" }, { status: 502 });
  }
  const bytes = Buffer.from(await res.arrayBuffer());
  if (bytes.length === 0 || bytes.length > 10 * 1024 * 1024) {
    return NextResponse.json({ error: "Generated image was empty or over 10 MB" }, { status: 502 });
  }
  const ext = contentType.includes("png") ? "png" : contentType.includes("webp") ? "webp" : "jpg";
  const path = `website/generated-${Date.now()}.${ext}`;
  const db = createServerClient();
  let ref: string;
  try {
    ref = await uploadBytes(db, BUCKETS.assets, path, bytes, contentType);
  } catch (e) {
    return NextResponse.json({ error: e instanceof Error ? e.message : "Storage upload failed" }, { status: 500 });
  }
  const base = (process.env.NEXT_PUBLIC_SUPABASE_URL ?? "").replace(/\/$/, "");
  const storedUrl = `${base}/storage/v1/object/public/${BUCKETS.assets}/${path}`;
  let mediaRecorded = false;
  try {
    await getPayloadPool().query(
      `INSERT INTO payload.media (url, filename, alt) VALUES ($1, $2, $3)`,
      [storedUrl, path.split("/").pop() ?? path, prompt.slice(0, 200)],
    );
    mediaRecorded = true;
  } catch {
    mediaRecorded = false;
  }
  return NextResponse.json({
    url: storedUrl,
    ref,
    prompt,
    keyed: Boolean(key),
    media_recorded: mediaRecorded,
    bytes: bytes.length,
  });
}
